CREATE TABLE ${primehrSchema}.ld_completion_case (
 id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,enrollment_id VARCHAR(36) NOT NULL,training_order_id VARCHAR(36) NOT NULL,training_order_fingerprint VARCHAR(64) NOT NULL,offering_id VARCHAR(36) NOT NULL,offering_version INT NOT NULL,offering_fingerprint VARCHAR(64) NOT NULL,employee_id BIGINT NOT NULL,employee_no VARCHAR(100) NOT NULL,employee_name VARCHAR(300) NOT NULL,appointment_id BIGINT NOT NULL,employee_fingerprint VARCHAR(64) NOT NULL,planned_hours DECIMAL(9,2) NOT NULL,credited_hours DECIMAL(9,2) NOT NULL,status VARCHAR(30) NOT NULL,content_revision INT NOT NULL,submitted_by VARCHAR(100),submitted_at DATETIMEOFFSET,verified_by VARCHAR(100),verified_at DATETIMEOFFSET,completion_date DATE,decision_reason VARCHAR(3000),completion_fingerprint VARCHAR(64),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT fk_ld_completion_enrollment FOREIGN KEY(enrollment_id) REFERENCES ${primehrSchema}.ld_enrollment(id),CONSTRAINT fk_ld_completion_order FOREIGN KEY(training_order_id) REFERENCES ${primehrSchema}.ld_training_order_source(id),CONSTRAINT fk_ld_completion_offering FOREIGN KEY(offering_id) REFERENCES ${primehrSchema}.ld_offering(id),CONSTRAINT uk_ld_completion_enrollment UNIQUE(agency_id,enrollment_id),CONSTRAINT ck_ld_completion_status CHECK(status IN ('DRAFT','FOR_VERIFICATION','COMPLETED','NOT_COMPLETED')),CONSTRAINT ck_ld_completion_values CHECK(offering_version>=1 AND planned_hours>0 AND credited_hours>=0 AND credited_hours<=planned_hours AND content_revision>=1));
CREATE INDEX ix_ld_completion_employee ON ${primehrSchema}.ld_completion_case(agency_id,employee_no,status);CREATE INDEX ix_ld_completion_offering ON ${primehrSchema}.ld_completion_case(agency_id,offering_id,status);
CREATE TABLE ${primehrSchema}.ld_session_attendance (
 id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,completion_case_id VARCHAR(36) NOT NULL,session_id VARCHAR(36) NOT NULL,session_title VARCHAR(200) NOT NULL,starts_at DATETIMEOFFSET NOT NULL,ends_at DATETIMEOFFSET NOT NULL,planned_hours DECIMAL(9,2) NOT NULL,status VARCHAR(20) NOT NULL,attended_hours DECIMAL(9,2) NOT NULL,credited_hours DECIMAL(9,2) NOT NULL,remarks VARCHAR(2000),recorded_by VARCHAR(100),recorded_at DATETIMEOFFSET,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT fk_ld_attendance_completion FOREIGN KEY(completion_case_id) REFERENCES ${primehrSchema}.ld_completion_case(id),CONSTRAINT fk_ld_attendance_session FOREIGN KEY(session_id) REFERENCES ${primehrSchema}.ld_offering_session(id),CONSTRAINT uk_ld_attendance_case_session UNIQUE(agency_id,completion_case_id,session_id),CONSTRAINT ck_ld_attendance_status CHECK(status IN ('UNRECORDED','PRESENT','PARTIAL','ABSENT')),CONSTRAINT ck_ld_attendance_values CHECK(ends_at>starts_at AND planned_hours>0 AND attended_hours>=0 AND credited_hours>=0 AND attended_hours<=planned_hours AND credited_hours<=attended_hours AND credited_hours<=planned_hours));
CREATE INDEX ix_ld_attendance_case ON ${primehrSchema}.ld_session_attendance(agency_id,completion_case_id,starts_at);
CREATE TABLE ${primehrSchema}.ld_completion_output (
 id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,completion_case_id VARCHAR(36) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,title VARCHAR(300) NOT NULL,description VARCHAR(3000) NOT NULL,status VARCHAR(20) NOT NULL,submitted_by VARCHAR(100),submitted_at DATETIMEOFFSET,verified_by VARCHAR(100),verified_at DATETIMEOFFSET,decision_reason VARCHAR(2000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT fk_ld_output_completion FOREIGN KEY(completion_case_id) REFERENCES ${primehrSchema}.ld_completion_case(id),CONSTRAINT uk_ld_completion_output_code UNIQUE(agency_id,completion_case_id,normalized_code),CONSTRAINT ck_ld_output_status CHECK(status IN ('REQUIRED','SUBMITTED','VERIFIED','WAIVED')));
CREATE INDEX ix_ld_output_case ON ${primehrSchema}.ld_completion_output(agency_id,completion_case_id,status);
CREATE TABLE ${primehrSchema}.ld_completion_evidence (
 id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,completion_case_id VARCHAR(36) NOT NULL,output_id VARCHAR(36),evidence_type VARCHAR(20) NOT NULL,original_filename VARCHAR(255) NOT NULL,storage_provider VARCHAR(30) NOT NULL,storage_object_key VARCHAR(500) NOT NULL,media_type VARCHAR(120) NOT NULL,byte_size BIGINT NOT NULL,checksum VARCHAR(64) NOT NULL,certificate_number VARCHAR(200),certificate_issuer VARCHAR(300),certificate_issue_date DATE,uploaded_by VARCHAR(100) NOT NULL,uploaded_at DATETIMEOFFSET NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT fk_ld_evidence_completion FOREIGN KEY(completion_case_id) REFERENCES ${primehrSchema}.ld_completion_case(id),CONSTRAINT fk_ld_evidence_output FOREIGN KEY(output_id) REFERENCES ${primehrSchema}.ld_completion_output(id),CONSTRAINT ck_ld_evidence_type CHECK(evidence_type IN ('OUTPUT','CERTIFICATE','ATTENDANCE','OTHER')),CONSTRAINT ck_ld_evidence_values CHECK(byte_size>0 AND ((evidence_type='OUTPUT' AND output_id IS NOT NULL) OR (evidence_type<>'OUTPUT' AND output_id IS NULL)) AND (evidence_type<>'CERTIFICATE' OR (certificate_number IS NOT NULL AND certificate_issuer IS NOT NULL AND certificate_issue_date IS NOT NULL))));
CREATE INDEX ix_ld_evidence_case ON ${primehrSchema}.ld_completion_evidence(agency_id,completion_case_id,uploaded_at);CREATE INDEX ix_ld_evidence_output ON ${primehrSchema}.ld_completion_evidence(agency_id,output_id);
